class intBool{constructor(t,...e){this.value=0;for(let r=0;r<e.length;r++)this.value|=!!e[r]<<t+r}setBool(t,e){"number"==typeof e&&(e=!!e);let r=this.value;if(Array.isArray(t))for(let l=0;l<t.length;l++)Array.isArray(e)?(r&=~(1<<t[l]),r|=e[l]<<t[l]):(r&=~(1<<t[l]),r|=e<<t[l]);else r&=~(1<<t),r|=e<<t;this.value=r}getBool(t){let e=1<<t;if(!(t<0||t>=32))return!!(this.value&e)}getNumber(){return this.value}getArray(){let t=[];for(let e=0;e<=31;e++)t.push(!!(this.value&2**e));return t}}window.intBool=intBool;